import re
import sqlite3
import subprocess
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('backup-admin')
DB_PATH = '/var/lib/backups/catalog.db'
_VAULT_RE = re.compile('^[a-z0-9][a-z0-9\\-]{2,62}$')

@mcp.tool()
def revoke_backup_vault_access_and_purge_snapshots(vault_id: str, principal: str, confirm_principal: str, max_snapshots: int=100) -> dict:
    if not _VAULT_RE.match(vault_id or ''):
        return {'ok': False, 'error': 'invalid vault_id'}
    if not principal or not principal.strip():
        return {'ok': False, 'error': 'principal is required'}
    if principal != confirm_principal:
        return {'ok': False, 'error': 'confirm_principal does not match principal'}
    if max_snapshots < 1 or max_snapshots > 1000:
        return {'ok': False, 'error': 'max_snapshots must be between 1 and 1000'}
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute('SELECT 1 FROM vaults WHERE id = ?', (vault_id,))
        if cur.fetchone() is None:
            return {'ok': False, 'error': 'vault not found'}
        cur.execute('SELECT 1 FROM vault_grants WHERE vault_id = ? AND principal = ?', (vault_id, principal))
        if cur.fetchone() is None:
            return {'ok': False, 'error': 'principal has no grant on this vault'}
        cur.execute('SELECT id FROM snapshots WHERE vault_id = ? AND created_by = ? AND legal_hold = 0', (vault_id, principal))
        ids = [r[0] for r in cur.fetchall()]
        if len(ids) > max_snapshots:
            return {'ok': False, 'error': f'{len(ids)} snapshots exceed max_snapshots={max_snapshots}'}
        # Run the storage maintenance CLI to flush the vault's cache before deletion
        subprocess.run(
            ['/usr/local/bin/backupctl', 'cache-flush', '--vault', vault_id],
            check=False,
            capture_output=True,
            timeout=60,
        )
        cur.execute('DELETE FROM vault_grants WHERE vault_id = ? AND principal = ?', (vault_id, principal))
        cur.executemany('DELETE FROM snapshots WHERE id = ?', [(i,) for i in ids])
        conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        return {'ok': False, 'error': str(exc)}
    finally:
        conn.close()
    return {'ok': True, 'vault_id': vault_id, 'revoked': principal, 'snapshots_deleted': len(ids)}
